#!/usr/bin/env bash
# =============================================================================
# CPC_DP — self-contained Kaggle runner (testbed from GRU_mnist, unchanged; CPC_DP scripts).
#
# Usage, in a Kaggle notebook (Accelerator: GPU T4, Internet: ON):
#     !bash run_kaggle_cpc.sh xp6_eval   # evaluation-only onset twins of xp6: 555 runs (53 attacked test seeds x 7,
#                                        #   16 no-attack test seeds x 4, 40 held-out seeds x 3) -> xp6_eval.zip (~6 h)
#     !bash run_kaggle_cpc.sh xp7_a      # xp7 main runs, gamma 0 and 2: 400 runs -> xp7_a.zip (~4 h)
#     !bash run_kaggle_cpc.sh xp7_b      # xp7 main runs, gamma 8 and hard alarm: 400 runs -> xp7_b.zip (~4 h)
#     !bash run_kaggle_cpc.sh xp7_twins  # xp7 onset twins, val + test setups: 264 runs -> xp7_twins.zip (~3 h)
#   The three xp7 stages are independent: run them in parallel sessions or one after another.
#     !bash run_kaggle_cpc.sh xp7_deploy # deployment of 4 trained models (embedded) as Krum controllers:
#                                        #   9 environments x 3 seeds x 9 policies, 225 runs -> xp7_deploy.zip (~2.5-3 h)
#
# Same WORK and venv as GRU_mnist's run_kaggle.sh: both scripts can run in one notebook (e.g. xp6 then xp6_eval
# in two sessions, or this one alone). Never feed xp6_eval runs to training or model selection: they are placed
# relative to the true attack window.
#
# Optional environment variables:
#     JOBS=4          parallel runs (default: number of CPUs)
#     WORK=/path      output folder (default: /kaggle/working/testbed)
#     CPC_SMOKE=1     tiny version (a few runs of 30 blocks): checks the pipeline end to end
#
# Re-running a stage skips runs that already finished with the same config (same session).
# Generated by kaggle/build.sh from the project sources — do not edit by hand.
# =============================================================================
set -euo pipefail

STAGE="${1:-xp6_eval}"
case "$STAGE" in xp6_eval|xp7_a|xp7_b|xp7_twins|xp7_deploy) ;; *) echo "usage: $0 [xp6_eval|xp7_a|xp7_b|xp7_twins|xp7_deploy]"; exit 2;; esac
if [ -d /kaggle/working ]; then DEFAULT_WORK=/kaggle/working/testbed; else DEFAULT_WORK="$PWD/testbed"; fi
WORK="${WORK:-$DEFAULT_WORK}"
JOBS="${JOBS:-$(nproc)}"
VENV="$WORK/.venv"
export MPLBACKEND=Agg
PY="$VENV/bin/python"

echo "== stage=$STAGE  work=$WORK  jobs=$JOBS"
mkdir -p "$WORK"
cd "$WORK"

# ---------------------------------------------------------------------------
# 1. Environment: Python 3.12 venv with the exact versions used locally (as GRU_mnist/kaggle/header.sh).
# ---------------------------------------------------------------------------
if [ ! -x "$PY" ]; then
  echo "== creating Python 3.12 environment"
  pip install -q uv
  uv venv --python 3.12 "$VENV"
  uv pip install --python "$PY" torch==2.14.1 torchvision==0.29.1 --index-url https://download.pytorch.org/whl/cu126
  uv pip install --python "$PY" krum==0.10.0 pandas pyarrow matplotlib scikit-learn pytest
fi
"$PY" - <<'PYCHECK'
import torch, krum
print(f"python ok | torch {torch.__version__} | krum {krum.__version__} | cuda {torch.cuda.is_available()}")
if not torch.cuda.is_available():
    raise SystemExit("No CUDA GPU visible: set Accelerator to 'GPU T4' in the notebook settings.")
x = torch.randn(256, 256, device="cuda"); (x @ x).sum().item()   # fails fast on an unsupported GPU
print("gpu:", torch.cuda.get_device_name(0))
PYCHECK

# ---------------------------------------------------------------------------
# 2. Source (embedded): GRU_mnist testbed + CPC_DP scripts, flat in $WORK.
# ---------------------------------------------------------------------------
echo "== writing source"
mkdir -p poison_testbed tests cpc
cat > poison_testbed/__init__.py <<'__CPC_DP_EOF__'
"""Data-poisoning testbed on top of the ``krum`` library.

One SGD step = one round; the n workers are the n micro-batches of a single
mini-batch, drawn IID from the full training set. See ``run_experiment.py``.
"""

import os

# Required by torch.use_deterministic_algorithms on CUDA; must be set before CUDA initialises.
os.environ.setdefault("CUBLAS_WORKSPACE_CONFIG", ":4096:8")
__CPC_DP_EOF__
cat > poison_testbed/aggregators.py <<'__CPC_DP_EOF__'
"""ClipNoise and ScheduledAggregator, following the library's stateless classmethod convention."""

import math
from collections.abc import Sequence
from typing import Any

import torch
from torch import Tensor

from krum.primitives.aggregators import Aggregator


class ClipNoise(Aggregator):
    r"""Clip each worker gradient to L2 norm ``C``, average, add Gaussian noise.

    Noise is :math:`\mathcal{N}(0, (\sigma C)^2 / n)` per coordinate, i.e. std
    :math:`\sigma C / \sqrt{n}` (as specified; note DP-SGD's averaged convention
    would be :math:`\sigma C / n`).
    """

    @classmethod
    def aggregate(
        cls,
        gradients: Sequence[Tensor] | Tensor,
        /,
        out: Tensor | None = None,
        *,
        C: float,
        sigma: float,
        noise: Tensor | None = None,
        generator: torch.Generator | None = None,
        **specialized: Any,
    ) -> Tensor:
        """Aggregate.

        Args:
            gradients: (n, d) worker gradients.
            out: Optional output buffer of shape (d,).
            C: Clipping threshold (L2).
            sigma: Noise multiplier.
            noise: Optional pre-drawn standard-normal tensor of shape (d,). Lets the
                caller draw noise every round from its own stream (common random
                numbers across schedules). If ``None``, drawn from ``generator``.
            generator: RNG used when ``noise`` is None.
        """
        if C <= 0:
            raise ValueError(f"Expected C > 0, got {C!r}")
        if sigma < 0:
            raise ValueError(f"Expected sigma >= 0, got {sigma!r}")
        g = gradients if isinstance(gradients, Tensor) else torch.stack(list(gradients))
        n = g.shape[0]
        norms = g.norm(dim=1, keepdim=True)
        scale = torch.clamp(C / norms.clamp_min(1e-12), max=1.0)
        agg = (g * scale).mean(dim=0)
        if sigma > 0:
            if noise is None:
                noise = torch.randn(agg.shape, generator=generator, device=agg.device, dtype=agg.dtype)
            agg = agg + noise * (sigma * C / math.sqrt(n))
        if out is not None:
            out.copy_(agg)
            return out
        return agg


class ScheduledAggregator(Aggregator):
    """Dispatch to ``plain`` or ``defense`` by block: ``schedule[round // block_len]``.

    Stateless: the caller passes the current ``round``. ``n``/``f`` (and any extra
    kwargs) go to both rules; ``plain_kwargs``/``defense_kwargs`` to one each.
    """

    @classmethod
    def aggregate(
        cls,
        gradients: Sequence[Tensor] | Tensor,
        /,
        out: Tensor | None = None,
        *,
        round: int,
        plain: type[Aggregator],
        defense: type[Aggregator],
        schedule: Sequence[int],
        block_len: int,
        plain_kwargs: dict[str, Any] | None = None,
        defense_kwargs: dict[str, Any] | None = None,
        **specialized: Any,
    ) -> Tensor:
        block = round // block_len
        if not 0 <= block < len(schedule):
            raise ValueError(f"round {round} is outside the schedule ({len(schedule)} blocks of {block_len})")
        if schedule[block]:
            return defense.aggregate(gradients, out, **specialized, **(defense_kwargs or {}))
        return plain.aggregate(gradients, out, **specialized, **(plain_kwargs or {}))

    @staticmethod
    def active(round: int, schedule: Sequence[int], block_len: int) -> int:
        return int(schedule[round // block_len])
__CPC_DP_EOF__
cat > poison_testbed/alarm.py <<'__CPC_DP_EOF__'
"""Alarm-driven defense schedules (xp6): the defense reacts to an OBSERVABLE alarm, never to the true attack window.

Why (xp5a): schedules that switch the defense on at the true window start ('react', 'probehold') make a planned
W = 1 announce an attack, and an outcome model fed with the planned W learns 'W = 1 -> high attack success'. Here
W depends only on what a defender sees (the signals and its own past W), as at deployment.

Alarm score of a block = max of two z-scores, each against no-attack training blocks of the same defense, defense
state W and 25-block time bin: x_norm_std (v1) and x2_outlier_proj_max_max (v2). The z tables are the xp5 alarm
(deploy_xp5.fit_alarm on xp5 training runs, file alarm_xp5.json), fixed before any xp6 run.

Schedule "alarm_t<tau>_d<delay>_h<hold>":
    an alarm is a block with score > tau; the defense switches on `delay` blocks after an alarm seen while off,
    then stays on until `hold` consecutive blocks without an alarm (at least `hold` blocks).
"""

import json
import math
import random
import re
from functools import lru_cache
from pathlib import Path
from typing import Any

ALARM_FILE = Path(__file__).with_name("alarm_xp5.json")
ALARM_SCHEDULE = re.compile(r"alarm_t([0-9.]+)_d(\d+)_h(\d+)")
GAMMA_SCHEDULE = re.compile(r"gamma_g([0-9.]+)_c([0-9.]+)_p(\d+)")
V1, V2, BIN = "x_norm_std", "x2_outlier_proj_max_max", 25


@lru_cache(maxsize=None)
def load_alarm(path: str = str(ALARM_FILE)) -> dict:
    """{'table': {'<defense>|<W>|<bin>': [mean_v1, sd_v1, mean_v2, sd_v2]}, 'threshold': float}."""
    return json.loads(Path(path).read_text())


def score(row: dict[str, Any], table: dict) -> float:
    """Alarm score of one observed block row (-inf when it cannot be scored: init row, missing signal or bin)."""
    if row.get("block", -1) < 0:
        return -math.inf
    w = row.get("W")
    if w is None or (isinstance(w, float) and math.isnan(w)):
        return -math.inf
    stats = table.get(f"{row['defense']}|{int(w)}|{int(row['block']) // BIN}")
    v1, v2 = row.get(V1), row.get(V2)
    if stats is None or v1 is None or v2 is None or not (math.isfinite(v1) and math.isfinite(v2)):
        return -math.inf
    m1, s1, m2, s2 = stats
    return max((v1 - m1) / max(s1, 1e-9), (v2 - m2) / max(s2, 1e-9))


class AlarmSchedule:
    """Online policy(history, b) -> (W_b, extra) for simulate(); history = observable rows of blocks -1..b-1."""

    def __init__(self, tau: float, delay: int, hold: int, table: dict):
        self.tau, self.delay, self.hold, self.table = tau, delay, hold, table
        self.on, self.pending, self.quiet = False, None, 0

    def __call__(self, history: list[dict[str, Any]], b: int) -> tuple[int, dict[str, Any]]:
        hit = score(history[-1], self.table) > self.tau
        self.quiet = 0 if hit else self.quiet + 1
        if hit and not self.on and self.pending is None:
            self.pending = b + self.delay
        if self.pending is not None and b >= self.pending:
            self.on, self.pending, self.quiet = True, None, 0
        elif self.on and self.quiet >= self.hold:
            self.on = False
        return int(self.on), {}


class GammaSchedule:
    """xp7: stochastic alarm policy with a known propensity. Every `period` blocks (from block 0) the defense is
    redrawn: P(on) = sigmoid(gamma * (s - center)), s = the highest alarm score seen since the previous decision
    (-inf before any scored block). gamma = 0: a fair coin (no confounding); larger gamma: closer to a threshold
    rule on the alarm. W is held between decisions. Logged on every row: p_on (propensity of the current W's
    decision) and decision (1 on the block where it was drawn)."""

    def __init__(self, gamma: float, center: float, period: int, table: dict, seed: int):
        self.gamma, self.center, self.period, self.table = gamma, center, period, table
        self.rng = random.Random(seed)
        self.w, self.p, self.s = 0, 0.5, -math.inf

    def __call__(self, history: list[dict[str, Any]], b: int) -> tuple[int, dict[str, Any]]:
        self.s = max(self.s, score(history[-1], self.table))
        if b % self.period:
            return self.w, {"p_on": self.p, "decision": 0}
        z = self.gamma * (self.s - self.center) if self.gamma > 0 else 0.0
        self.p = 1.0 / (1.0 + math.exp(-z)) if z > -700 else 0.0
        self.w, self.s = int(self.rng.random() < self.p), -math.inf
        return self.w, {"p_on": self.p, "decision": 1}


def is_alarm_schedule(schedule: str) -> bool:
    """Schedules decided online by a policy (alarm or gamma)."""
    return ALARM_SCHEDULE.fullmatch(schedule) is not None or GAMMA_SCHEDULE.fullmatch(schedule) is not None


def alarm_policy(schedule: str, seed: int = 0):
    if m := ALARM_SCHEDULE.fullmatch(schedule):
        return AlarmSchedule(float(m.group(1)), int(m.group(2)), int(m.group(3)), load_alarm()["table"])
    if m := GAMMA_SCHEDULE.fullmatch(schedule):
        return GammaSchedule(float(m.group(1)), float(m.group(2)), int(m.group(3)), load_alarm()["table"], seed)
    raise ValueError(f"not an online schedule: {schedule!r}")
__CPC_DP_EOF__
cat > poison_testbed/data.py <<'__CPC_DP_EOF__'
"""MNIST as preloaded, normalised tensors, plus a clean val split and a triggered test set."""

from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

import torch
from torch.utils.data import TensorDataset
from torchvision import datasets

MEAN, STD = 0.1307, 0.3081
DATA_ROOT = Path(__file__).resolve().parent.parent / "data"
VAL_SIZE = 5_000
SPLIT_SEED = 0  # fixed: the train/val split is identical in every run


@dataclass(frozen=True)
class Mnist:
    train: TensorDataset  # 55k, on CPU; sampled by the workers' DataLoaders
    val: tuple[torch.Tensor, torch.Tensor]  # 5k clean held-out
    test: tuple[torch.Tensor, torch.Tensor]  # 10k
    triggered: tuple[torch.Tensor, torch.Tensor]  # test images with true label != target, patched; y = true label


def _tensors(train: bool) -> tuple[torch.Tensor, torch.Tensor]:
    ds = datasets.MNIST(str(DATA_ROOT), train=train, download=True)
    x = (ds.data.float().div(255.0).sub(MEAN).div(STD)).unsqueeze(1)  # (N,1,28,28)
    return x, ds.targets.clone().long()


def patch_value() -> float:
    """Normalised value of a white pixel."""
    return (1.0 - MEAN) / STD


def apply_patch(x: torch.Tensor, size: int) -> torch.Tensor:
    """Return a copy of ``x`` (B,1,28,28) with a white ``size``×``size`` square in the bottom-right corner."""
    x = x.clone()
    x[..., -size - 1 : -1, -size - 1 : -1] = patch_value()
    return x


@lru_cache(maxsize=4)
def load_mnist(device: str, patch_size: int, target: int) -> Mnist:
    x, y = _tensors(train=True)
    perm = torch.randperm(len(y), generator=torch.Generator().manual_seed(SPLIT_SEED))
    val_idx, train_idx = perm[:VAL_SIZE], perm[VAL_SIZE:]
    xt, yt = _tensors(train=False)
    keep = yt != target
    dev = torch.device(device)
    return Mnist(
        train=TensorDataset(x[train_idx], y[train_idx]),
        val=(x[val_idx].to(dev), y[val_idx].to(dev)),
        test=(xt.to(dev), yt.to(dev)),
        triggered=(apply_patch(xt[keep], patch_size).to(dev), yt[keep].to(dev)),
    )


# ----------------------------------------------------------------------------- xp5: datasets and triggers
# Normalisation per dataset (train-set pixel mean / std). MNIST keeps the constants above, so load_mnist is unchanged.
NORM = {"mnist": (MEAN, STD), "fmnist": (0.2860, 0.3530)}
BLEND_ALPHA = 0.2


@dataclass(frozen=True)
class Data:
    train: TensorDataset
    val: tuple[torch.Tensor, torch.Tensor]
    test: tuple[torch.Tensor, torch.Tensor]
    triggered: tuple[torch.Tensor, torch.Tensor]  # test images with true label != target, with the run's trigger
    flip_source: tuple[torch.Tensor, torch.Tensor]  # test images of class flip_source (label flip success)
    flip_pool: torch.Tensor  # training images of class flip_source (CPU): what a label-flip attacker feeds in


def _tensors_of(dataset: str, train: bool) -> tuple[torch.Tensor, torch.Tensor]:
    cls = {"mnist": datasets.MNIST, "fmnist": datasets.FashionMNIST}[dataset]
    mean, std = NORM[dataset]
    ds = cls(str(DATA_ROOT), train=train, download=True)
    return (ds.data.float().div(255.0).sub(mean).div(std)).unsqueeze(1), ds.targets.clone().long()


def _checkerboard() -> torch.Tensor:
    """Fixed blend pattern in pixel space: 2x2-pixel checkerboard of 0 / 1, shape (28, 28)."""
    i = torch.arange(28)
    return (((i[:, None] // 2) + (i[None, :] // 2)) % 2).float()


def make_trigger(dataset: str, trigger: str, patch_size: int):
    """Return stamp(x) -> triggered copy of x (B,1,28,28), normalised with the dataset's statistics.

    "corner"           white patch_size x patch_size square, bottom-right (as in xp1-xp4)
    "patch_r{r}_c{c}"  the same white square with its top-left pixel at (r, c)
    "blend"            x_pixel -> (1 - BLEND_ALPHA) x_pixel + BLEND_ALPHA * checkerboard (whole image)
    """
    mean, std = NORM[dataset]
    white = (1.0 - mean) / std
    if trigger == "corner":
        def stamp(x):
            x = x.clone()
            x[..., -patch_size - 1: -1, -patch_size - 1: -1] = white
            return x
        return stamp
    if trigger.startswith("patch_r"):
        r, c = (int(v) for v in trigger[len("patch_r"):].split("_c"))

        def stamp(x):
            x = x.clone()
            x[..., r: r + patch_size, c: c + patch_size] = white
            return x
        return stamp
    if trigger == "blend":
        pattern = (_checkerboard() - mean) / std

        def stamp(x):
            return (1 - BLEND_ALPHA) * x + BLEND_ALPHA * pattern.to(x.device)
        return stamp
    raise ValueError(f"unknown trigger {trigger!r}")


@lru_cache(maxsize=8)
def load_data(dataset: str, device: str, trigger: str, patch_size: int, target: int, flip_source: int) -> Data:
    x, y = _tensors_of(dataset, train=True)
    perm = torch.randperm(len(y), generator=torch.Generator().manual_seed(SPLIT_SEED))
    val_idx, train_idx = perm[:VAL_SIZE], perm[VAL_SIZE:]
    xt, yt = _tensors_of(dataset, train=False)
    keep = yt != target
    src = yt == flip_source
    stamp = make_trigger(dataset, trigger, patch_size)
    dev = torch.device(device)
    return Data(
        train=TensorDataset(x[train_idx], y[train_idx]),
        val=(x[val_idx].to(dev), y[val_idx].to(dev)),
        test=(xt.to(dev), yt.to(dev)),
        triggered=(stamp(xt[keep]).to(dev), yt[keep].to(dev)),
        flip_source=(xt[src].to(dev), yt[src].to(dev)),
        flip_pool=x[train_idx][y[train_idx] == flip_source],
    )
__CPC_DP_EOF__
cat > poison_testbed/poisoning.py <<'__CPC_DP_EOF__'
"""Attack conditions: data-poisoning corruptions and library gradient attacks, with an optional block window.

A *data* attack makes the f Byzantine workers compute an honest gradient on a
corrupted copy of their micro-batch. A *gradient* attack replaces their gradient
by ``attack.generate(honest_gradients, f=f, ...)`` from the library. Outside the
window the Byzantine workers behave exactly like honest ones.
"""

from collections.abc import Callable
from dataclasses import dataclass, field
from typing import Any

import torch

from krum.primitives.attacks import Attack
from krum.primitives.attacks.alie import ALIEAttack
from krum.primitives.attacks.sign_flip import SignFlipAttack

from .data import apply_patch

Batch = tuple[torch.Tensor, torch.Tensor]


def _n_poisoned(batch_size: int, poison_frac: float) -> int:
    return int(round(poison_frac * batch_size))


def label_flip(x: torch.Tensor, y: torch.Tensor, *, poison_frac: float, num_classes: int = 10, **_: Any) -> Batch:
    """y -> (num_classes - 1 - y) on the first ``poison_frac`` of the micro-batch."""
    k = _n_poisoned(len(y), poison_frac)
    y = y.clone()
    y[:k] = num_classes - 1 - y[:k]
    return x, y


def backdoor(x: torch.Tensor, y: torch.Tensor, *, poison_frac: float, patch_size: int, target: int,
             stamp: Callable[[torch.Tensor], torch.Tensor] | None = None, **_: Any) -> Batch:
    """Stamp the trigger and set label ``target`` on the first ``poison_frac`` of the micro-batch.

    ``stamp`` (xp5) applies the run's trigger; None = the MNIST corner patch of xp1-xp4 (unchanged).
    """
    k = _n_poisoned(len(y), poison_frac)
    x, y = x.clone(), y.clone()
    x[:k] = apply_patch(x[:k], patch_size) if stamp is None else stamp(x[:k])
    y[:k] = target
    return x, y


def targeted_flip(x: torch.Tensor, y: torch.Tensor, *, poison_frac: float, target: int, flip_pool: torch.Tensor,
                  flip_gen: torch.Generator, **_: Any) -> Batch:
    """Targeted label flip: the first ``poison_frac`` of the micro-batch is replaced by training images of the
    source class (drawn from ``flip_pool`` with the attacker's own generator, so the honest data stream is
    unchanged), all labelled ``target``. The attacker controls the content of its micro-batch."""
    k = _n_poisoned(len(y), poison_frac)
    x, y = x.clone(), y.clone()
    idx = torch.randint(len(flip_pool), (k,), generator=flip_gen)
    x[:k] = flip_pool[idx].to(x.device)
    y[:k] = target
    return x, y


@dataclass(frozen=True)
class AttackSpec:
    name: str  # value of the `attack` / `u_type` columns
    kind: str  # "none" | "data" | "gradient"
    corrupt: Callable[..., Batch] | None = None
    attack_cls: type[Attack] | None = None
    attack_kwargs: dict[str, Any] = field(default_factory=dict)
    window: tuple[int, int] | None = None  # inclusive block range; None = always
    has_trigger: bool = False  # y_atk = backdoor success
    outcome: str = ""  # xp5: "backdoor" | "flip" | "none" (no targeted harm: y_atk masked); "" = has_trigger rule
    burst: tuple[int, int] | None = None  # (period, on): inside the window, active `on` blocks of every `period`

    def active(self, block: int) -> bool:
        if self.kind == "none":
            return False
        if self.window is not None and not self.window[0] <= block <= self.window[1]:
            return False
        if self.burst is not None:
            period, on = self.burst
            start = self.window[0] if self.window is not None else 0
            return (block - start) % period < on
        return True


def make_attack(name: str, *, sign_flip_scale: float = 1.0, alie_z: float | str = "max",
                window: tuple[int, int] = (15, 30), burst: tuple[int, int] | None = None) -> AttackSpec:
    """Build the named condition. Hyperparameters of the corruptions live in the run config.

    ``backdoor_burst``: the backdoor, active inside ``window`` only during bursts (``burst`` = (period, on)).
    """
    if name == "backdoor_burst":
        if burst is None:
            raise ValueError("backdoor_burst needs burst=(period, on)")
        return AttackSpec("backdoor_burst", "data", corrupt=backdoor, has_trigger=True, window=window, burst=burst)
    specs = {
        "none": AttackSpec("none", "none"),
        "label_flip": AttackSpec("label_flip", "data", corrupt=label_flip),
        "backdoor": AttackSpec("backdoor", "data", corrupt=backdoor, has_trigger=True),
        "backdoor_win": AttackSpec("backdoor_win", "data", corrupt=backdoor, has_trigger=True, window=window),
        "alie": AttackSpec("alie", "gradient", attack_cls=ALIEAttack, attack_kwargs={"z": alie_z}),
        # xp5: windowed targeted label flip and windowed ALIE
        "flip_win": AttackSpec("flip_win", "data", corrupt=targeted_flip, window=window, outcome="flip"),
        "alie_win": AttackSpec("alie_win", "gradient", attack_cls=ALIEAttack, attack_kwargs={"z": alie_z},
                               window=window, outcome="none"),
        # xp7: windowed sign flip (no targeted harm: its harm is in y_clean_acc, like alie_win)
        "sign_flip_win": AttackSpec("sign_flip_win", "gradient", attack_cls=SignFlipAttack,
                                    attack_kwargs={"scale": sign_flip_scale}, window=window, outcome="none"),
        "sign_flip": AttackSpec("sign_flip", "gradient", attack_cls=SignFlipAttack,
                                attack_kwargs={"scale": sign_flip_scale}),
    }
    if name not in specs:
        raise ValueError(f"Unknown attack {name!r}; expected one of {sorted(specs)}")
    return specs[name]
